const COUNT = BATCH_COUNT;
const taggedPath = path.join(__dirname, "models-tagged.json");
let output = APPEND && fs.existsSync(taggedPath)
  ? JSON.parse(fs.readFileSync(taggedPath, "utf8"))
  : [];

if (!Array.isArray(output)) output = [];

for (const model of raw.slice(BATCH_START, BATCH_START + COUNT)) {
  const mapping = MAPPING[model.fileName];
  const baseName = model.fileName.split("/").pop().replace(/\.glb$/i, "");
  const fallbackName = baseName
    .replace(/^\d+_/, "")
    .split("_")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
  output.push({
    fileName: model.fileName,
    name: mapping ? mapping.name : fallbackName,
    modelUrl: `${MODEL_BASE_URL}${model.fileName.split("/").pop()}`,
    tags: mapping
      ? mapping.tags
      : ["3d", "model", "görsel", "sahne", "sunum"],
    category: mapping ? mapping.category : "diger",
    tier: "free",
  });
}

fs.writeFileSync(
  taggedPath,
  JSON.stringify(output, null, 1) + "\n",
  "utf8"
);

console.log(`Kacar ogeler yazildi: ${output.length}`);

const seen = new Map();
for (const item of output) seen.set(item.fileName, item);
const unique = [...seen.values()];
if (unique.length !== output.length) {
  output = unique;
  fs.writeFileSync(
    taggedPath,
    JSON.stringify(output, null, 1) + "\n",
    "utf8"
  );
  console.log(`Tekrarlar temizlendi: ${unique.length} benzersiz oge`);
}

for (const item of output.slice(0, 3)) {
  console.log(JSON.stringify(item, null, 2));
}
